public enum NeoTrixError {

    
    
    case InitFailed
    case InvalidInput
    case OperationFailed
    case NotInitialized
    case SerializationError
    case NetworkError
    case PermissionDenied
    case NotFound
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNeoTrixError: FfiConverterRustBuffer {
    typealias SwiftType = NeoTrixError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NeoTrixError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InitFailed
        case 2: return .InvalidInput
        case 3: return .OperationFailed
        case 4: return .NotInitialized
        case 5: return .SerializationError
        case 6: return .NetworkError
        case 7: return .PermissionDenied
        case 8: return .NotFound

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: NeoTrixError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .InitFailed:
            writeInt(&buf, Int32(1))
        
        
        case .InvalidInput:
            writeInt(&buf, Int32(2))
        
        
        case .OperationFailed:
            writeInt(&buf, Int32(3))
        
        
        case .NotInitialized:
            writeInt(&buf, Int32(4))
        
        
        case .SerializationError:
            writeInt(&buf, Int32(5))
        
        
        case .NetworkError:
            writeInt(&buf, Int32(6))
        
        
        case .PermissionDenied:
            writeInt(&buf, Int32(7))
        
        
        case .NotFound:
            writeInt(&buf, Int32(8))
        
        }
    }
}


extension NeoTrixError: Equatable, Hashable {}

extension NeoTrixError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterSequenceFloat: FfiConverterRustBuffer {
    typealias SwiftType = [Float]

    public static func write(_ value: [Float], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterFloat.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [Float] {
        let len: Int32 = try readInt(&buf)
        var seq = [Float]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterFloat.read(from: &buf))
        }
        return seq
    }
}

